var EU_PTR_SIZE				= 4;
var EU_INT_SIZE				= 4;
var EU_DWORD_SIZE			= 4;
var EU_BOOL_SIZE			= 4;

var EU_TRUE 				= 1;
var EU_FALSE 				= 0;

