EndUser.prototype.DevelopData = function(envelopedData, 
	senderCert, onSuccess, onError) {
	if (this.m_euKSP.IsPrivateKeyReaded()) {
		this.m_euKSP.DevelopData(
			envelopedData, senderCert, onSuccess, onError);
	} else {
		try {
			if (this.m_pkContext == null) {
				this.m_euSign.RaiseError(EU_ERROR_BAD_CERT);
				return;
			}

			var senderInfo = this.m_euSign.CtxDevelopData(
				this.m_pkContext, envelopedData, senderCert);

			onSuccess(senderInfo.GetTransferableObject());
		} catch (e) {
			onError(e);
		}
	}
};

