EndUser.prototype.CtxFree = function(context, onSuccess, onError) {
	try {
		context = EndUserInitFromTransferableObject(context, EndUserContext);
		this.m_euSign.CtxFree(context);
		onSuccess();
	} catch (e) {
		onError(e);
	}
};

