EndUser.prototype.CtxSetParameter = function(
	context, name, value, onSuccess, onError) {
	try {
		if (!context) {
			context = this.m_context;
		} else {
			context = EndUserInitFromTransferableObject(
				context, EndUserContext);
		}

		this.m_euSign.CtxSetParameter(context, name, value);

		onSuccess();
	} catch (e) {
		onError(e);
	}
};

